using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.EventSystems;using UnityEngine.SceneManagement;using UnityEngine.UI;using System.IO;
public static class JiesuanRebuildSafe {const string R="Assets/Resources/Settlement",L=R+"/Prefabs/Leaf",P=R+"/Prefabs/JiesuanFixed.prefab",S="Assets/Scenes/jiesuan_fixed.unity";[MenuItem("Tools/UI/Rebuild Jiesuan Safe")]
public static void Rebuild(){Directory.CreateDirectory(R+"/Prefabs");if(File.Exists(P))AssetDatabase.DeleteAsset(P);var page=new GameObject("jiesuan",typeof(RectTransform));page.GetComponent<RectTransform>().sizeDelta=new Vector2(1080,1920);foreach(var g in AssetDatabase.FindAssets("t:Prefab",new[]{L})){var src=AssetDatabase.LoadAssetAtPath<GameObject>(AssetDatabase.GUIDToAssetPath(g));if(src!=null)PrefabUtility.InstantiatePrefab(src,page.transform);}PrefabUtility.SaveAsPrefabAsset(page,P);Object.DestroyImmediate(page);EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var c=new GameObject("Canvas",typeof(RectTransform),typeof(Canvas),typeof(CanvasScaler),typeof(GraphicRaycaster));c.GetComponent<Canvas>().renderMode=RenderMode.ScreenSpaceOverlay;c.GetComponent<CanvasScaler>().referenceResolution=new Vector2(1080,1920);PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(P),c.transform);new GameObject("EventSystem",typeof(EventSystem),typeof(StandaloneInputModule));EditorSceneManager.SaveScene(SceneManager.GetActiveScene(),S);AssetDatabase.SaveAssets();AssetDatabase.Refresh();}}
